-- One-time guarded V79 legacy frequency and time-series tables
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='35s';
SELECT pg_advisory_xact_lock(-987654319::bigint);
CREATE TEMP TABLE reviewed_batch(draft bigint, source int, fp text, draft_hash text, source_hex text, snapshot jsonb, wizard jsonb, metadata text, flat_ar text, flat_en text) ON COMMIT DROP;
INSERT INTO reviewed_batch VALUES
(604,429,$mw$1457A87CEB3D4013773F8A912F64A5FE3342C6DE7E6CB2CA801C6FDED9032E2F$mw$,$mw$fcd1d365016fd0c784057ca7111dd1f8$mw$,$mw$$mw$,$mw${"Id":429,"Points":10,"Options":[{"Id":1705,"Order":1,"IsCorrect":false,"LatexCode":"20"},{"Id":1706,"Order":2,"IsCorrect":false,"LatexCode":"28"},{"Id":1707,"Order":3,"IsCorrect":true,"LatexCode":"30"},{"Id":1708,"Order":4,"IsCorrect":false,"LatexCode":"22"}],"StageId":2,"TitleAr":"استخلاص إجمالي البيانات من مخطط بفئات متمايزة","TitleEn":"Combine counts from mutually exclusive chart categories","CategoryId":22,"QuestionTextAr":"يبين مخطط أن 8 طلاب يذهبون مشياً و12 بالدراجة و10 بالحافلة. كم العدد الكلي؟","QuestionTextEn":"A chart shows 8 pupils walk, 12 cycle and 10 take a bus. What is the total?","DetailedSolutionAr":"المبدأ المستخدم: مجموع فئات الرسم البياني غير المتداخلة يساوي العدد الكلي. بيانات المشي 8 وركوب الدراجات 12 والحافلة 10 طلاب. نجمع 8 + 12 + 10 = 30 طالباً. نفترض أن كل طالب محسوب في فئة واحدة فقط، حتى لا يحدث عدّ مزدوج.","DetailedSolutionEn":"Rule used: Sum the disjoint categories in a chart to find the total. There are 8 walkers, 12 cyclists and 10 bus riders. Add 8 + 12 + 10 = 30 pupils. Each pupil is counted once.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null}$mw$::jsonb,$mw${"Hints":[{"Ar":"اقرأ تكرار كل وسيلة نقل.","En":"Read the frequency for each transport mode."},{"Ar":"اجمع الفئات الثلاث.","En":"Add all three categories."}],"Title":{"Ar":"قراءة جدول تكراري","En":"Reading a frequency table"},"Points":10,"Options":[{"Reason":{"Ar":"حسب المشي والدراجة وأغفل الحافلة.","En":"This adds walking and cycling but omits bus riders."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"20"},{"Reason":{"Ar":"بعد جمع 8 و12 نحصل على 20. للوصول إلى 28 أضيفت 8 أخرى، بينما فئة الحافلة فيها 10.","En":"Walking and cycling total 20. Adding another 8 gives 28, but the bus count is 10."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"28"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"30"},{"Reason":{"Ar":"حسب الدراجة والحافلة وأغفل المشي.","En":"This adds cycling and bus riders but leaves out walkers."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"22"}],"StageId":2,"Question":{"Ar":"يسجل الجدول وسيلة النقل الرئيسية لكل طالب مرة واحدة. يشير $A$ إلى المشي و$B$ إلى الدراجة و$C$ إلى الحافلة، و$n$ إلى عدد الطلاب. $\\begin{array}{cccc} & A & B & C \\\\ n & 8 & 12 & 10 \\end{array}$ كم طالباً شمل السجل كله؟","En":"The table records each pupil once by main travel mode. $A$ means walking, $B$ cycling and $C$ bus. The row $n$ gives pupil counts. $\\begin{array}{cccc} & A & B & C \\\\ n & 8 & 12 & 10 \\end{array}$ How many pupils are in the whole record?"},"Solution":{"Idea":{"Ar":"مجموع التكرارات يعطي عدد المشاهدات.","En":"The sum of frequencies gives the number of observations."},"Unit":{"Ar":"طالباً","En":"pupils"},"Steps":[{"Ar":"نجمع عمودي المشي والدراجة: $8+12=20$.","En":"Add the walking and cycling columns: $8+12=20$."},{"Ar":"نضم طلاب الحافلة فنحصل على $20+10=30$.","En":"Include the bus riders to get $20+10=30$."}],"Result":{"Ar":"$30$","En":"$30$"},"CommonError":{"Ar":"لا تستبعد فئة من المجموع.","En":"Do not omit a category."},"FormulaLatex":"N=\\sum_i f_i","Substitution":{"Ar":"$8+12+10=30$","En":"$8+12+10=30$"},"Verification":{"Ar":"$30-10=20=8+12$","En":"$30-10=20=8+12$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":100,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اقرأ تكرار كل وسيلة نقل.","En":"Read the frequency for each transport mode."},{"Ar":"اجمع الفئات الثلاث.","En":"Add all three categories."}],"Solution":{"Idea":{"Ar":"مجموع التكرارات يعطي عدد المشاهدات.","En":"The sum of frequencies gives the number of observations."},"Unit":{"Ar":"طالباً","En":"pupils"},"Steps":[{"Ar":"نجمع عمودي المشي والدراجة: $8+12=20$.","En":"Add the walking and cycling columns: $8+12=20$."},{"Ar":"نضم طلاب الحافلة فنحصل على $20+10=30$.","En":"Include the bus riders to get $20+10=30$."}],"Result":{"Ar":"$30$","En":"$30$"},"CommonError":{"Ar":"لا تستبعد فئة من المجموع.","En":"Do not omit a category."},"FormulaLatex":"N=\\sum_i f_i","Substitution":{"Ar":"$8+12+10=30$","En":"$8+12+10=30$"},"Verification":{"Ar":"$30-10=20=8+12$","En":"$30-10=20=8+12$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"حسب المشي والدراجة وأغفل الحافلة.","En":"This adds walking and cycling but omits bus riders."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"بعد جمع 8 و12 نحصل على 20. للوصول إلى 28 أضيفت 8 أخرى، بينما فئة الحافلة فيها 10.","En":"Walking and cycling total 20. Adding another 8 gives 28, but the bus count is 10."},"Order":2},{"ErrorType":"","Reason":{"Ar":"","En":""},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"حسب الدراجة والحافلة وأغفل المشي.","En":"This adds cycling and bus riders but leaves out walkers."},"Order":4}]}$mw$,$mw$مجموع التكرارات يعطي عدد المشاهدات.

$N=\sum_i f_i$

1. نجمع عمودي المشي والدراجة: $8+12=20$.

2. نضم طلاب الحافلة فنحصل على $20+10=30$.

$30$

طالباً

$30-10=20=8+12$

لا تستبعد فئة من المجموع.$mw$,$mw$The sum of frequencies gives the number of observations.

$N=\sum_i f_i$

1. Add the walking and cycling columns: $8+12=20$.

2. Include the bus riders to get $20+10=30$.

$30$

pupils

$30-10=20=8+12$

Do not omit a category.$mw$),
(778,824,$mw$678BE7EF4658ED3824F21BB51C1CEFF02413937B3800AAFB032774D166704F2E$mw$,$mw$d8d5b2ad72fd8c184096d53488e8df97$mw$,$mw$$mw$,$mw${"Id":824,"Points":10,"Options":[{"Id":3285,"Order":1,"IsCorrect":false,"LatexCode":"9"},{"Id":3286,"Order":2,"IsCorrect":false,"LatexCode":"4"},{"Id":3287,"Order":3,"IsCorrect":false,"LatexCode":"17"},{"Id":3288,"Order":4,"IsCorrect":true,"LatexCode":"12"}],"StageId":2,"TitleAr":"تحديد أكبر تغير موجب بين نقطتين متتاليتين","TitleEn":"Find the largest positive change in sequential line-chart values","CategoryId":22,"QuestionTextAr":"يعرض مخطط خطي أربع قراءات متتالية: 14 ثم 23 ثم 19 ثم 31. ما مقدار أكبر زيادة بين قراءتين متتاليتين؟","QuestionTextEn":"A line chart shows four successive values: 14, 23, 19, and 31. What is the largest increase between consecutive points?","DetailedSolutionAr":"المبدأ المستخدم: أكبر زيادة بين نقطتين متتاليتين تعني أكبر فرق موجب (القيمة التالية − السابقة). للفترات: 23 − 14 = +9، ثم 19 − 23 = −4 وهو انخفاض، ثم 31 − 19 = +12. أكبر زيادة هي +12.","DetailedSolutionEn":"Rule used: Largest consecutive increase means the largest positive next-minus-previous change. The differences are 23 − 14 = +9, 19 − 23 = −4 (a decrease), and 31 − 19 = +12. The largest increase is 12.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null}$mw$::jsonb,$mw${"Hints":[{"Ar":"قارن النقاط المتتالية فقط.","En":"Compare consecutive points only."},{"Ar":"احسب فروق القيم المتتابعة واختر أكبر زيادة موجبة.","En":"Calculate successive differences and select the largest positive increase."}],"Title":{"Ar":"أكبر زيادة بين قراءتين","En":"Largest increase between readings"},"Points":10,"Options":[{"Reason":{"Ar":"تسعة هي الزيادة الأولى، وهناك زيادة أكبر لاحقاً.","En":"Nine is the first increase, but a larger increase follows."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"9"},{"Reason":{"Ar":"أربعة هي مقدار الانخفاض من 23 إلى 19.","En":"Four is the size of the decrease from 23 to 19."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":{"Ar":"سبعة عشر هي الزيادة بين أول قراءة وآخر قراءة، وهما غير متتاليتين.","En":"Seventeen compares the first and last readings, which are not consecutive."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"17"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"12"}],"StageId":2,"Question":{"Ar":"يبيّن الجدول القراءات $v$ بالترتيب الزمني $t$. $\\begin{array}{crrrr}t&1&2&3&4\\\\v&14&23&19&31\\end{array}$ ما مقدار أكبر زيادة بين قراءتين متتاليتين؟","En":"The table shows readings $v$ in time order $t$. $\\begin{array}{crrrr}t&1&2&3&4\\\\v&14&23&19&31\\end{array}$ What is the largest increase between consecutive readings?"},"Solution":{"Idea":{"Ar":"الزيادة بين نقطتين متتاليتين هي الفرق الموقّع بين قيمتيهما.","En":"An increase between consecutive points is the signed difference of their values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"التغير الأول $23-14=9$، والثاني $19-23=-4$.","En":"The first change is $23-14=9$ and the second is $19-23=-4$."},{"Ar":"التغير الأخير $31-19=12$. نقارن الزيادتين فنجد أن 12 أكبر من 9.","En":"The final change is $31-19=12$. Of the two increases, 12 exceeds 9."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"لا تقارن أول قيمة بآخر قيمة أو تعدّ الانخفاض زيادة.","En":"Do not compare endpoints or count decreases as increases."},"FormulaLatex":"\\max_i(x_{i+1}-x_i)","Substitution":{"Ar":"$23-14=9,\\quad19-23=-4,\\quad31-19=12$","En":"$23-14=9,\\quad19-23=-4,\\quad31-19=12$"},"Verification":{"Ar":"$12>9>-4$","En":"$12>9>-4$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":100,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قارن النقاط المتتالية فقط.","En":"Compare consecutive points only."},{"Ar":"احسب فروق القيم المتتابعة واختر أكبر زيادة موجبة.","En":"Calculate successive differences and select the largest positive increase."}],"Solution":{"Idea":{"Ar":"الزيادة بين نقطتين متتاليتين هي الفرق الموقّع بين قيمتيهما.","En":"An increase between consecutive points is the signed difference of their values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"التغير الأول $23-14=9$، والثاني $19-23=-4$.","En":"The first change is $23-14=9$ and the second is $19-23=-4$."},{"Ar":"التغير الأخير $31-19=12$. نقارن الزيادتين فنجد أن 12 أكبر من 9.","En":"The final change is $31-19=12$. Of the two increases, 12 exceeds 9."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"لا تقارن أول قيمة بآخر قيمة أو تعدّ الانخفاض زيادة.","En":"Do not compare endpoints or count decreases as increases."},"FormulaLatex":"\\max_i(x_{i+1}-x_i)","Substitution":{"Ar":"$23-14=9,\\quad19-23=-4,\\quad31-19=12$","En":"$23-14=9,\\quad19-23=-4,\\quad31-19=12$"},"Verification":{"Ar":"$12>9>-4$","En":"$12>9>-4$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"تسعة هي الزيادة الأولى، وهناك زيادة أكبر لاحقاً.","En":"Nine is the first increase, but a larger increase follows."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"أربعة هي مقدار الانخفاض من 23 إلى 19.","En":"Four is the size of the decrease from 23 to 19."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"سبعة عشر هي الزيادة بين أول قراءة وآخر قراءة، وهما غير متتاليتين.","En":"Seventeen compares the first and last readings, which are not consecutive."},"Order":3},{"ErrorType":"","Reason":{"Ar":"","En":""},"Order":4}]}$mw$,$mw$الزيادة بين نقطتين متتاليتين هي الفرق الموقّع بين قيمتيهما.

$\max_i(x_{i+1}-x_i)$

1. التغير الأول $23-14=9$، والثاني $19-23=-4$.

2. التغير الأخير $31-19=12$. نقارن الزيادتين فنجد أن 12 أكبر من 9.

$12$

بلا وحدة قياس

$12>9>-4$

لا تقارن أول قيمة بآخر قيمة أو تعدّ الانخفاض زيادة.$mw$,$mw$An increase between consecutive points is the signed difference of their values.

$\max_i(x_{i+1}-x_i)$

1. The first change is $23-14=9$ and the second is $19-23=-4$.

2. The final change is $31-19=12$. Of the two increases, 12 exceeds 9.

$12$

Dimensionless

$12>9>-4$

Do not compare endpoints or count decreases as increases.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF btrim(coalesce(b.wizard#>>'{Question,Ar}',''))='' OR btrim(coalesce(b.wizard#>>'{Question,En}',''))='' OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(b.wizard#>>'{Question,Ar}'),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(b.wizard#>>'{Question,En}'),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Revised stem duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" q WHERE q."Id"<>b.draft AND q."EditorialStatus" NOT IN ('Published','Withdrawn') AND (q."WizardJson"::jsonb#>>'{Question,Ar}'=b.wizard#>>'{Question,Ar}' OR q."WizardJson"::jsonb#>>'{Question,En}'=b.wizard#>>'{Question,En}')) THEN RAISE EXCEPTION 'Revised open draft duplicate: %',b.draft; END IF;
  UPDATE "Problems" SET "QuestionTextAr"=b.wizard#>>'{Question,Ar}',"QuestionTextEn"=b.wizard#>>'{Question,En}',"TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
